    privacySection: 'Privacy',
    privacyIntro: 'How ScanPlay uses and protects your data.',
    privacyDeleteHint:
      'You can delete your account from this screen. You must type OK then press Continue. ScanPlay then deletes your Supabase account and linked data. Other providers (payments, analytics, AI) may keep traces under their own rules.',
    privacyOpen: 'Read the privacy policy',
    privacyUpdated: 'Last updated: September 2026',
    privacyClose: 'Close',
    privacyFullPolicy: 'Read the full policy',
    termsOpen: 'Terms of use',
    privacyPolicy1: 'ScanPlay (scanplay.org) is published by El Fahmi, Ikram (Belgium, no. 1037.806.166). Contact: support@scanplay.org.',
    privacyPolicy2: 'Account data: email, optional Google sign-in, display name, avatar, progress (XP, streak, decks, mistakes, achievements, wallet), subscription and preferences (language, theme, sounds).',
    privacyPolicy3: 'Cloud sync via Supabase when signed in. Profile visible to friends: name, avatar, stats and unlocked achievements. Coach messages and related usage may be stored.',
    privacyPolicy4: 'Without an account, the scan is read in the browser. When signed in, the image may be sent to OpenAI long enough to extract cards; ScanPlay does not keep the original file. Card text and a thumbnail may remain. Speaking practice may send a short audio clip to Groq.',
    privacyPolicy5: 'Multiplayer: room code, scores and lobby presence, stored while the feature is used.',
    privacyPolicy6:
      'ScanPlay does not sell your data. You can delete your account in Settings (confirm by typing OK then Continue). The app then deletes your Supabase account and ScanPlay data (decks, stats, coach, social links) plus related local copies. You may also request access at support@scanplay.org.',
    privacyAboutHeading: 'About',
    privacyPolicy7: 'ScanPlay is an independent project created by Bilal El Fahmi. The goal: make studying simpler and more motivating through games, without replacing your course material.',
    privacyPolicy8: 'Progressive web app available at scanplay.org. For questions, feedback or suggestions: support@scanplay.org.',
    privacyPolicy9:
      'Plus/Pro/Max subscriptions are billed via Stripe. About 65% of the subscription fee is allocated to user-facing AI costs (OCR scans, coach); the rest covers running the service. Plan changes are only available after your current paid period ends, once automatic renewal is canceled. Dates and usage are in Settings.',
    privacyPolicy10:
      'Audience measurement: Google Analytics and Vercel Analytics. A banner may ask for your consent. Google AdSense currently serves no ads in the app. Details: full policy.',
    privacyPolicyMinors:
      'ScanPlay is intended for people aged 13 or over. At sign-up, a checkbox lets you declare that: it is not an identity check, and parental consent is not collected. If an account belongs to someone under 13, email support@scanplay.org.',
    devPlan: 'Plan (dev test)',
