    lpBenefit3Body: 'De score van elke stap zegt wat vastzit en wat je opnieuw moet doen.',
    lpGameTitle: 'Een reden om morgen terug te komen',
    lpGameSub: 'ScanPlay gebruikt de mechanieken van de games die je al kent.',
    lpGameXpTitle: 'XP en niveaus',
    lpGameXpBody: 'Tien XP per juist antwoord, en een niveau dat stijgt naarmate je herhaalt.',
    lpGameStreakTitle: 'Reeks van dagen',
    lpGameStreakBody:
      'Een dag gespeeld, een dag extra in je reeks. De mijlpalen liggen op 3, 7 en 30 dagen.',
    lpGameAchTitle: 'Prestaties en kisten',
    lpGameAchBody:
      '{n} prestaties om vrij te spelen, elke dag een kist om te openen en munten voor bonussen.',
    lpProofTitle: 'Zij herhalen met ScanPlay',
    lpFaqTitle: 'De vragen die je je stelt',
    lpFaqSub: 'Staat het antwoord er niet bij? Schrijf ons.',
    lpFaq1Q: 'Is het echt gratis?',
    lpFaq1A:
      'Ja. Je eerste proefscan heeft geen account nodig en gebruikt ScanPlay AI niet (je blijft op 0% na het aanmaken van een account). Er is geen dagelijkse scanquota. Met een gratis account wordt je geschiedenis bewaard en krijg je een ScanPlay AI-enveloppe (€0,15/week): scans, coach en samenvattingen delen hetzelfde %. Eén proefscan per apparaat (pagina vernieuwen geeft geen nieuwe). Betaalde abonnementen vergroten de enveloppe; niets verplicht je.',
    lpFaq2Q: 'Moet ik een account maken?',
    lpFaq2A:
      'Niet om je eerste blad te scannen. Een gratis account wordt gevraagd om de spellen te starten en je voortgang te bewaren. De proef zonder account is beperkt tot 1 scan per apparaat. Daarna heb je een account nodig. Die eerste scan verbruikt je AI-gebruik % niet.',
    lpFaq3Q: 'Met welke documenten werkt het?',
    lpFaq3A:
      'Met afbeeldingen: een foto van je blad, een pagina uit een handboek, of een schermafbeelding. Gedrukte of netjes geschreven tekst wordt het best herkend. PDF wordt nog niet ondersteund.',
    lpFaq4Q: 'En als de scan zich vergist?',
    lpFaq4A:
      'Je ziet alle kaarten voor je speelt. Je kunt een woord verbeteren, verwijderen of toevoegen en dan het pad starten.',
    lpFaq5Q: 'Werkt het op een gsm?',
    lpFaq5A:
      'ScanPlay is in de eerste plaats voor de gsm gemaakt en installeert rechtstreeks vanuit je browser als een app, zonder store. Het werkt ook op de computer.',
    lpFaq6Q: 'Blijven mijn lessen privé?',
    lpFaq6A:
      'Je bladen horen bij je account en zijn niet openbaar. Wat we bewaren, staat in het privacybeleid.',
    lpFinalTitle: 'Je volgende herhaling begint met een foto.',
    lpFinalSub:
      'Neem je blad, scan het, speel. Het kost je minder tijd dan het nog eens te herlezen.',
