    lpProduct3Title: 'Tus fallos en un solo sitio',
    lpProduct3Body:
      'Lo que fallas se reúne en un espacio propio, para repetirlo sin rehacer la ficha entera.',
    lpProblemKicker: 'El problema real',
    lpProblemTitle: 'Releer los apuntes no es repasarlos.',
    lpProblemBody:
      'Lees tres veces, todo te suena, das por hecho que lo sabes. El día del examen, nada. Releer es pasivo: tu cerebro reconoce el texto en lugar de recuperarlo.',
