    privacyPolicy1: 'ScanPlay (scanplay.org) está editado por El Fahmi, Ikram (Bélgica, n.º 1037.806.166). Contacto: support@scanplay.org.',
    privacyPolicy2: 'Datos de cuenta: email, acceso opcional con Google, nombre, avatar, progreso (XP, racha, mazos, errores, logros, monedero), suscripción y preferencias.',
    privacyPolicy3: 'Sincronización en la nube vía Supabase al iniciar sesión. Perfil visible para amigos: nombre, avatar, stats y logros. Los mensajes del coach pueden guardarse.',
    privacyPolicy4: 'Sin cuenta, el escaneo se lee en el navegador. Con sesión, la imagen puede enviarse a OpenAI el tiempo de extraer tarjetas; ScanPlay no guarda el archivo original. El texto de las tarjetas y una miniatura pueden quedar. La pronunciación puede enviar audio corto a Groq.',
    privacyPolicy5: 'Multijugador: código de sala, puntuaciones y presencia mientras se usa la función.',
    privacyPolicy6:
      'ScanPlay no vende tus datos. Puedes eliminar tu cuenta en Ajustes (confirma escribiendo OK y Continuar). La app borra entonces tu cuenta de Supabase y tus datos ScanPlay más las copias locales. También puedes pedir acceso en support@scanplay.org.',
    privacyAboutHeading: 'Acerca de',
    privacyPolicy7: 'ScanPlay es un proyecto independiente creado por Bilal El Fahmi. El objetivo: hacer el repaso más simple y motivador con juegos, sin sustituir tu curso.',
    privacyPolicy8: 'Aplicación web progresiva (PWA) en scanplay.org. Para preguntas, sugerencias o comentarios: support@scanplay.org.',
    privacyPolicy9:
      'Suscripciones Plus/Pro/Max con Stripe. Alrededor del 65 % de la cuota se destina a costes de IA del usuario (escaneos OCR, coach); el resto cubre el servicio. Los cambios de plan solo al final del periodo pagado, tras cancelar la renovación. Fechas y uso en Ajustes.',
    privacyPolicy10:
      'Medición de audiencia: Google Analytics y Vercel Analytics. Un banner puede pedir tu consentimiento. Google AdSense no muestra anuncios en la app por ahora. Detalles: política completa.',
    privacyPolicyMinors:
      'ScanPlay está destinado a personas de al menos 13 años. Al registrarte, una casilla te permite declararlo: no es una verificación de identidad y no se recoge consentimiento parental. Si una cuenta pertenece a alguien menor de 13 años, escribe a support@scanplay.org.',
