    lpFaq1Q: "هل هو مجاني فعلاً؟",
    lpFaq1A: "نعم. مسح التجربة الأول لا يحتاج حساباً ولا يستخدم ScanPlay AI (تبقى عند 0% بعد إنشاء الحساب). لا توجد حصّة مسح يومية. وبحساب مجاني يُحفظ سجلّك وتحصل على غلاف ScanPlay AI (0,15 €/أسبوع): المسح والمدرب والملخصات يتشاركون نفس النسبة. تجربة واحدة فقط لكل جهاز (تحديث الصفحة لا يمنح أخرى). الباقات المدفوعة توسّع الغلاف؛ لا شيء يُجبرك عليها.",
