    privacyPolicy2: "Kontodaten: E-Mail, optional Google-Anmeldung, Anzeigename, Avatar, Fortschritt (XP, Serie, Blätter, Fehler, Erfolge, Wallet), Abo und Einstellungen (Sprache, Theme, Sounds).",
    privacyPolicy3: "Cloud-Sync über Supabase, wenn du angemeldet bist. Profil sichtbar für deine Freunde: Anzeigename, Avatar, Stats und freigeschaltete Erfolge. Coach-Nachrichten und zugehörige Nutzung können gespeichert werden.",
    privacyPolicy4: "Ohne Konto wird der Scan im Browser gelesen. Angemeldet kann das Bild kurz an OpenAI gesendet werden, um Karten zu extrahieren; ScanPlay behält die Originaldatei nicht. Kartentext und ein Vorschaubild können bleiben. Die Aussprache kann kurzes Audio an Groq senden.",
    privacyPolicy5: "Mehrspieler: Raumcode, Scores und Anwesenheit in der Lobby. Daten in der Datenbank, solange die Funktion genutzt wird.",
    privacyPolicy6: "ScanPlay verkauft deine Daten nicht. Du kannst dein Konto in den Einstellungen löschen (Bestätigung durch Tippen von OK und dann Weiter). Die App löscht dann dein Supabase-Konto und deine ScanPlay-Daten (Blätter, Stats, Coach, Verbindungen) sowie zugehörige lokale Kopien. Du kannst auch Zugang zu deinen Daten unter support@scanplay.org anfragen.",
    privacyAboutHeading: "Über uns",
    privacyPolicy7: "ScanPlay ist ein unabhängiges Projekt von Bilal El Fahmi. Ziel: Lernen einfacher und motivierender machen durch Spiele, ohne deinen Kurs zu ersetzen.",
    privacyPolicy8: "Progressive Web-App (PWA) unter scanplay.org. Bei Fragen, Ideen oder Feedback: support@scanplay.org.",
    privacyPolicy9: "Abos Plus/Pro/Max: Zahlung über Stripe. Ein Teil der Abo-Gebühren (etwa 65 %) fließt in nutzerseitige KI-Kosten (OCR-Scans, Coach); der Rest deckt den Betrieb des Dienstes. Ein Planwechsel ist erst am Ende der laufenden bezahlten Periode möglich, nach Kündigung der automatischen Verlängerung. Daten und Nutzung findest du in den Einstellungen.",
    privacyPolicy10: "Reichweitenmessung: Google Analytics und Vercel Analytics. Ein Banner kann um deine Zustimmung bitten. Google AdSense zeigt derzeit keine Anzeigen in der App. Details: vollständige Datenschutzerklärung.",
    privacyPolicyMinors: "ScanPlay richtet sich an Personen ab 13 Jahren. Bei der Registrierung kannst du das per Checkbox bestätigen: Das ist keine Identitätsprüfung, und es wird keine elterliche Einwilligung eingeholt. Betrifft ein Konto ein Kind unter 13 Jahren, schreib an support@scanplay.org.",
    devPlan: "Plan (Dev-Test)",
