export type TranslationKey = keyof typeof strings.fr;

const VALID_LOCALES: Locale[] = ['fr', 'en', 'nl', 'es', 'ar', 'de'];

/** Same rule as landing: fr* → fr, nl* → nl, es* → es, de* → de, else en (never force French). */
function localeFromNavigator(
  language = typeof navigator === 'undefined' ? 'en' : navigator.language,
): Locale {
  const tag = language.trim().toLowerCase().replace(/_/g, '-');
  if (tag === 'fr' || tag.startsWith('fr-')) return 'fr';
  if (tag === 'nl' || tag.startsWith('nl-')) return 'nl';
  if (tag === 'es' || tag.startsWith('es-')) return 'es';
  if (tag === 'de' || tag.startsWith('de-')) return 'de';
  if (tag === 'ar' || tag.startsWith('ar-')) return 'ar';
  return 'en';
}

export function getLocale(): Locale {
  const stored = localStorage.getItem(LOCALE_KEY);
  if (VALID_LOCALES.includes(stored as Locale)) return stored as Locale;
  return localeFromNavigator();
}

export function setLocale(locale: Locale): void {
  localStorage.setItem(LOCALE_KEY, locale);
}

export function t(key: TranslationKey, locale?: Locale): string {
  const loc = locale ?? getLocale();
  const table = strings[loc] as Record<TranslationKey, string>;
  return table[key] ?? strings.fr[key];
}

export function getDateLocale(locale: Locale): string {
  const map: Record<Locale, string> = {
    fr: 'fr-FR',
    en: 'en-US',
    nl: 'nl-NL',
    es: 'es-ES',
    ar: 'ar-SA',
    de: 'de-DE',
  };
  return map[locale];
}
